 layer.addEventListener('pointermove',e=>{const g=chartDrag;if(!g)return;const dx=(e.clientX-g.x0)/g.z,dy=(e.clientY-g.y0)/g.z;if(!g.moved&&Math.abs(dx)+Math.abs(dy)<4)return;g.moved=true;hideTip();if(g.resize){g.el.style.width=clampN(g.w0+dx,200,1200,g.w0)+'px';g.el.style.height=clampN(g.h0+dy,140,900,g.h0)+'px'}else{g.el.style.left=Math.max(44,g.l0+dx)+'px';g.el.style.top=Math.max(HEADERHEIGHT,g.t0+dy)+'px'}});
